1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import {
9	  registrarConfigured,
10	  checkDomains,
11	  registerDomain,
12	  renewDomain,
13	  domainInfo,
14	  listRecords,
15	  addRecord,
16	  deleteRecord,
17	  type RegistrantContact,
18	} from "./registrar";
19	import { domainTerm, domainTermPriceCents } from "./billing-terms";
20	import { debitWallet, InsufficientBalanceError } from "./wallet";
21	import { getSettingBool } from "./settings";
22	
23	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
24	
25	/* ------------------------------------------------------------------ *
26	 * Idempotency helpers
27	 *
28	 * Layer 1 (cheap, in-process): a short-window duplicate-submit guard keyed on
29	 * user+domain. Catches the double-click / impatient-retry case immediately and
30	 * keeps two concurrent requests from both reaching the registrar. Best-effort
31	 * only — it does not survive a restart or span multiple app instances.
32	 *
33	 * Layer 2 (authoritative, in the DB): `Domain.name` is UNIQUE and the
34	 * charge+create runs in one `$transaction`, so a duplicate can never both take
35	 * money and create a second row. Renewal is guarded by an in-transaction expiry
36	 * re-check (charge and expiry advance together atomically).
37	 * ------------------------------------------------------------------ */
38	
39	const SUBMIT_GUARD_MS = 120_000;
40	const inFlightSubmits = new Map<string, number>();
41	
42	function beginSubmit(key: string): boolean {
43	  const now = Date.now();
44	  const heldUntil = inFlightSubmits.get(key);
45	  if (heldUntil !== undefined && heldUntil > now) return false;
46	  if (inFlightSubmits.size > 2000) {
47	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
48	  }
49	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
50	  return true;
51	}
52	
53	function endSubmit(key: string): void {
54	  inFlightSubmits.delete(key);
55	}
56	
57	class DuplicateDomainError extends Error {
58	  constructor() {
59	    super("DUPLICATE_DOMAIN");
60	    this.name = "DuplicateDomainError";
61	  }
62	}
63	
64	const isUniqueConflict = (e: any) => e?.code === "P2002";
65	
66	type RegistrationVerdict = { state: "registered" | "not-registered" | "unknown"; expires?: Date };
67	
68	/**
69	 * After a registrar call fails or times out we must NOT assume the registration
70	 * did not happen — name.com may well have taken the order. Ask the registrar
71	 * before touching the customer's money:
72	 *  - the domain is in our reseller account  -> registered (keep the charge)
73	 *  - the domain is still purchasable        -> not registered (safe to refund)
74	 *  - anything else / registrar unreachable  -> unknown (never auto-refund)
75	 */
76	async function verifyRegistration(domain: string): Promise<RegistrationVerdict> {
77	  try {
78	    const info = await domainInfo(domain);
79	    return { state: "registered", expires: info.expires };
80	  } catch {
81	    /* not in our account, or the API is unhappy — fall through to availability */
82	  }
83	  try {
84	    const [check] = await checkDomains([domain]);
85	    if (check?.available === true) return { state: "not-registered" };
86	  } catch {
87	    /* registrar unreachable */
88	  }
89	  return { state: "unknown" };
90	}
91	
92	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
93	  const user = await requireUser();
94	  // Feature flag: domain registration can be switched off platform-wide.
95	  if (!(await getSettingBool("feature_domains", true))) {
96	    return { error: "Domain registration is currently unavailable." };
97	  }
98	  if (!registrarConfigured()) {
99	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
100	  }
101	  const contactSchema = z.object({
102	    firstName: z.string().min(1).max(60),
103	    lastName: z.string().min(1).max(60),
104	    address1: z.string().min(1).max(120),
105	    city: z.string().min(1).max(60),
106	    stateProvince: z.string().min(1).max(60),
107	    postalCode: z.string().min(1).max(20),
108	    country: z.string().length(2),
109	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
110	    email: z.string().email(),
111	  });
112	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
113	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
114	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
115	
116	  const contactParsed = contactSchema.safeParse({
117	    firstName: formData.get("firstName"),
118	    lastName: formData.get("lastName"),
119	    address1: formData.get("address1"),
120	    city: formData.get("city"),
121	    stateProvince: formData.get("stateProvince"),
122	    postalCode: formData.get("postalCode"),
123	    country: String(formData.get("country") ?? "").toUpperCase(),
124	    phone: formData.get("phone"),
125	    email: formData.get("email"),
126	  });
127	  if (!contactParsed.success) {
128	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
129	  }
130	
131	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
132	  const guardKey = `register:${user.id}:${domain}`;
133	  if (!beginSubmit(guardKey)) {
134	    return { error: "That registration is already being processed — give it a moment before retrying." };
135	  }
136	
137	  try {
138	    const existing = await db.domain.findUnique({ where: { name: domain } });
139	    if (existing) {
140	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
141	      if (existing.status === "PENDING") {
142	        return { error: "You already have a registration in progress for this domain." };
143	      }
144	      return { error: `You already have ${domain} on this account (status: ${existing.status.toLowerCase()}).` };
145	    }
146	
147	    // Live availability + retail(markup) & cost prices from name.com
148	    let priceCents: number; // retail per year (customer)
149	    let costCents: number; // registrar cost per year (us)
150	    try {
151	      const [check] = await checkDomains([domain]);
152	      if (!check) return { error: "Could not check availability. Try again." };
153	      if (!check.available) return { error: "Domain is not available." };
154	      if (check.premium) return { error: "Premium domains are not supported yet." };
155	      if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
156	      priceCents = check.priceCents;
157	      costCents = check.costCents;
158	    } catch (e: any) {
159	      return { error: String(e?.message ?? e).slice(0, 200) };
160	    }
161	
162	    const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
163	    const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
164	    if (user.balanceCents < totalCents) {
165	      return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
166	    }
167	
168	    let record;
169	    try {
170	      record = await db.$transaction(async (tx) => {
171	        // Re-check inside the transaction: the availability round-trip above is
172	        // slow enough for a second submit to slip in. `Domain.name` is UNIQUE, so
173	        // even if this read misses, the create below rolls the whole debit back.
174	        const dupe = await tx.domain.findUnique({ where: { name: domain }, select: { id: true } });
175	        if (dupe) throw new DuplicateDomainError();
176	        await debitWallet(tx, user.id, totalCents);
177	        await tx.walletTransaction.create({
178	          data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
179	        });
180	        return tx.domain.create({
181	          data: { name: domain, userId: user.id, priceCents, costCents, termYears: dTerm.years, status: "PENDING", registrar: "name.com" },
182	        });
183	      });
184	    } catch (e) {
185	      if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
186	      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
187	        return { error: "This domain is already being registered — you have not been charged twice." };
188	      }
189	      throw e;
190	    }
191	
192	    try {
193	      const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
194	      const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
195	      await db.domain.update({
196	        where: { id: record.id },
197	        data: {
198	          status: "ACTIVE",
199	          registeredAt: new Date(),
200	          expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
201	        },
202	      });
203	      await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
204	      await db.notification.create({
205	        data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
206	      });
207	    } catch (e: any) {
208	      const reason = String(e?.message ?? e).slice(0, 400);
209	      // NEVER refund blind: a timeout/5xx often means the order DID go through.
210	      const verdict = await verifyRegistration(domain);
211	
212	      if (verdict.state === "registered") {
213	        // The registration exists — keep the charge and finish the record.
214	        await db.domain.update({
215	          where: { id: record.id },
216	          data: {
217	            status: "ACTIVE",
218	            registeredAt: new Date(),
219	            expiresAt: verdict.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
220	            error: `Recovered after registrar error: ${reason}`.slice(0, 500),
221	          },
222	        });
223	        await db.auditLog.create({
224	          data: { userId: user.id, action: "domain.register.recovered", detail: `${domain}: ${reason}`.slice(0, 500) },
225	        });
226	        await db.notification.create({
227	          data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
228	        });
229	        redirect(`/dashboard/domains/${record.id}`);
230	      }
231	
232	      if (verdict.state === "not-registered") {
233	        // Confirmed still available at the registrar — refunding is safe.
234	        await db.$transaction([
235	          db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
236	          db.walletTransaction.create({
237	            data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
238	          }),
239	          db.domain.update({
240	            where: { id: record.id },
241	            data: { status: "FAILED", error: reason.slice(0, 500) },
242	          }),
243	        ]);
244	        return { error: `Registration failed: ${reason.slice(0, 200)} (you were refunded).` };
245	      }
246	
247	      // Unknown: leave PENDING and charged, flag for manual review. Refunding
248	      // here risks giving away a domain we actually paid the registrar for.
249	      await db.domain.update({
250	        where: { id: record.id },
251	        data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
252	      });
253	      await db.auditLog.create({
254	        data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
255	      });
256	      await db.notification.create({
257	        data: {
258	          userId: user.id,
259	          title: `Domain ${domain} needs review`,
260	          body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
261	          href: `/dashboard/domains/${record.id}`,
262	        },
263	      });
264	      return {
265	        error:
266	          `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
267	          `It is marked for review — do not retry, you will not be charged twice.`,
268	      };
269	    }
270	    redirect(`/dashboard/domains/${record.id}`);
271	  } finally {
272	    endSubmit(guardKey);
273	  }
274	}
275	
276	/** A renewal already landed if the registrar expiry runs ~a month past ours. */
277	const RENEW_SLACK_MS = 30 * 86400_000;
278	
279	export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
280	  const user = await requireUser();
281	  const domain = await db.domain.findUnique({ where: { id: domainId } });
282	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
283	  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
284	  if (domain.status === "FAILED") return { error: "This domain is not registered." };
285	
286	  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
287	  const guardKey = `renew:${domain.userId}:${domain.name}`;
288	  if (!beginSubmit(guardKey)) {
289	    return { error: "A renewal for this domain is already in progress." };
290	  }
291	
292	  try {
293	    const dTerm = domainTerm(domain.termYears);
294	    const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
295	    const owner = await db.user.findUnique({ where: { id: domain.userId } });
296	    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };
297	
298	    const dbExpiry = domain.expiresAt ?? null;
299	
300	    // Idempotency: charge and expiry advance together in one transaction below,
301	    // so if the registrar expiry is already ahead of ours a previous attempt
302	    // renewed but never got charged/recorded. Adopt that renewal instead of
303	    // buying a second year.
304	    let registrarExpiry: Date | undefined;
305	    try {
306	      registrarExpiry = (await domainInfo(domain.name)).expires;
307	    } catch {
308	      /* non-fatal: fall through to a normal renew */
309	    }
310	    const alreadyRenewed =
311	      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;
312	
313	    if (!alreadyRenewed) {
314	      try {
315	        await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
316	      } catch (e: any) {
317	        return { error: `Renewal failed: ${String(e?.message ?? e).slice(0, 200)}` };
318	      }
319	      registrarExpiry = await domainInfo(domain.name)
320	        .then((i) => i.expires)
321	        .catch(() => undefined);
322	    }
323	
324	    const targetExpiry =
325	      registrarExpiry ?? new Date((dbExpiry ?? new Date()).getTime() + dTerm.years * 365 * 86400_000);
326	
327	    try {
328	      const charged = await db.$transaction(async (tx) => {
329	        // Re-read under the transaction: if a concurrent request already advanced
330	        // the expiry it also already took the money — do not charge again.
331	        const fresh = await tx.domain.findUnique({ where: { id: domainId }, select: { expiresAt: true } });
332	        if (dbExpiry && fresh?.expiresAt && fresh.expiresAt.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS) {
333	          return false;
334	        }
335	        await debitWallet(tx, domain.userId, renewCents);
336	        await tx.walletTransaction.create({
337	          data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
338	        });
339	        await tx.domain.update({
340	          where: { id: domainId },
341	          data: { expiresAt: targetExpiry, status: "ACTIVE" },
342	        });
343	        return true;
344	      });
345	      if (!charged) {
346	        revalidatePath(`/dashboard/domains/${domainId}`);
347	        return {};
348	      }
349	    } catch (e) {
350	      if (e instanceof InsufficientBalanceError) {
351	        // The registrar renewal already succeeded — flag the uncollected charge
352	        // instead of silently swallowing it.
353	        await db.auditLog
354	          .create({
