393	export async function addDnsRecord(prev: any, formData: FormData): Promise<{ error?: string }> {
394	  const domainId = String(formData.get("domainId") ?? "");
395	  let ctx;
396	  try {
397	    ctx = await ownedDomain(domainId);
398	  } catch (e: any) {
399	    return { error: e.message };
400	  }
401	  const parsed = z
402	    .object({
403	      name: z.string().max(120).default(""),
404	      type: z.enum(RECORD_TYPES),
405	      address: z.string().min(1).max(500),
406	      ttl: z.coerce.number().int().min(60).max(86400).default(300),
407	      mxPref: z.coerce.number().int().min(0).max(65535).optional(),
408	    })
409	    .safeParse({
410	      name: formData.get("name") ?? "",
411	      type: formData.get("type"),
412	      address: formData.get("address"),
413	      ttl: formData.get("ttl") || 300,
414	      mxPref: formData.get("mxPref") || undefined,
415	    });
416	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid record." };
417	
418	  // "@" or blank => apex (name.com uses empty host for apex)
419	  const host = ["@", ""].includes(parsed.data.name.trim()) ? "" : parsed.data.name.trim();
420	  try {
421	    await addRecord(ctx.domain.name, {
422	      host,
423	      type: parsed.data.type,
424	      answer: parsed.data.address,
425	      ttl: parsed.data.ttl,
426	      priority: parsed.data.type === "MX" || parsed.data.type === "SRV" ? parsed.data.mxPref ?? 10 : undefined,
427	    });
428	  } catch (e: any) {
429	    return { error: String(e?.message ?? e).slice(0, 200) };
430	  }
431	  revalidatePath(`/dashboard/domains/${domainId}`);
432	  return {};
433	}
