1	// Pure, dependency-free wallet/card split math shared by the client wizards
2	// (DeployWizard, ResizePicker) and the server actions (payAndDeploy,
3	// resizeServer). Keeping it here — with NO server-only imports — guarantees the
4	// split the customer SEES is byte-for-byte the split that gets CHARGED.
5	
6	/**
7	 * Stripe rejects card charges under ~$0.50. We never send a card amount below
8	 * this; when the natural remainder would fall under it we leave exactly this
9	 * much on the card and apply slightly less wallet credit (see walletSplit).
10	 */
11	export const STRIPE_MIN_CENTS = 50;
12	
13	export type WalletSplit = {
14	  /** Cents taken from the customer's existing wallet balance. */
15	  walletApplied: number;
16	  /** Cents charged to the card (0 = fully paid from wallet, no Stripe). */
17	  cardCents: number;
18	  /** True when we bumped the card up to STRIPE_MIN_CENTS (reducing wallet). */
19	  clampedForStripeMin: boolean;
20	};
21	
22	/**
23	 * Split a due amount between the wallet and the card, honoring the customer's
24	 * "apply my balance" toggle and Stripe's minimum-charge floor.
25	 *
26	 * - `useWallet` off  → everything on the card.
27	 * - wallet covers all → cardCents = 0 (caller pays entirely from wallet, no Stripe).
28	 * - partial cover     → walletApplied = min(balance, due), card = the remainder.
29	 * - tiny remainder    → if 0 < card < STRIPE_MIN_CENTS and the wallet can't cover
30	 *   the whole thing, reduce walletApplied so exactly STRIPE_MIN_CENTS lands on the
31	 *   card (never send Stripe a sub-minimum charge). Integer-cent exact throughout.
32	 */
33	export function walletSplit(opts: {
34	  dueCents: number;
35	  balanceCents: number;
36	  useWallet: boolean;
37	}): WalletSplit {
38	  const dueCents = Math.max(0, Math.round(opts.dueCents));
39	  const balanceCents = Math.max(0, Math.round(opts.balanceCents));
40	  if (dueCents <= 0) return { walletApplied: 0, cardCents: 0, clampedForStripeMin: false };
41	
42	  let walletApplied = opts.useWallet ? Math.min(balanceCents, dueCents) : 0;
43	  let cardCents = dueCents - walletApplied;
44	  let clampedForStripeMin = false;
45	
46	  // A tiny non-zero card remainder that Stripe would reject. This only happens
47	  // when the wallet can't cover the whole charge (otherwise cardCents === 0), so
48	  // the least-surprising fix is to leave STRIPE_MIN_CENTS on the card and apply a
49	  // touch less wallet. Guarded so walletApplied can never go negative.
50	  if (cardCents > 0 && cardCents < STRIPE_MIN_CENTS && dueCents >= STRIPE_MIN_CENTS) {
51	    walletApplied = dueCents - STRIPE_MIN_CENTS;
52	    cardCents = STRIPE_MIN_CENTS;
53	    clampedForStripeMin = true;
54	  }
55	  return { walletApplied, cardCents, clampedForStripeMin };
56	}
