import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { checkDomains, registrarConfigured } from "@/lib/registrar";

/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
function clientIp(req: NextRequest): string {
  const xff = req.headers.get("x-forwarded-for") ?? "";
  const first = xff.split(",")[0]?.trim();
  return first || "unknown";
}

export async function GET(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  // Each call fans out to the registrar API — throttle per-IP so a customer
  // can't hammer the upstream registrar / rack up lookups.
  const rl = checkRateLimit(`domcheck:${clientIp(req)}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "rate limited", retryAfterSec: rl.retryAfterSec, results: [] },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const q = (req.nextUrl.searchParams.get("q") ?? "").toLowerCase().trim().replace(/[^a-z0-9.-]/g, "");
  if (q.length < 2) return NextResponse.json({ results: [] });
  if (!registrarConfigured()) {
    return NextResponse.json({ configured: false, results: [] });
  }

  const base = q.includes(".") ? q.slice(0, q.indexOf(".")) : q;
  const candidates = q.includes(".")
    ? [q, ...["com", "net", "io", "dev"].filter((t) => q !== `${base}.${t}`).map((t) => `${base}.${t}`)]
    : ["com", "net", "io", "dev", "app", "xyz"].map((t) => `${base}.${t}`);

  try {
    const checks = await checkDomains(candidates.slice(0, 8));
    return NextResponse.json({
      configured: true,
      results: checks.filter((c) => c.priceCents !== null),
    });
  } catch (e: any) {
    return NextResponse.json({ configured: true, error: String(e?.message ?? e).slice(0, 200), results: [] });
  }
}
