/**
 * Shared money + state helpers for INBOUND domain transfers (transfer-in).
 *
 * Plain server-side module (no "use server") so both the server action
 * (lib/actions-domains-transfer.ts) and the worker sweep (worker/billing.ts)
 * settle a transfer through exactly the same code — one definition of "what the
 * customer paid" and one definition of "credit it back", so the two paths can
 * never disagree about the amount or double-credit the same transfer.
 */

import { db } from "./db";
import { domainTermPriceCents } from "./billing-terms";

/** A transfer buys the domain plus a 1-year extension — always a single year. */
export const TRANSFER_TERM_YEARS = 1;

/**
 * ICANN's rule: a domain cannot be transferred within 60 days of its
 * registration or of a previous transfer. Surfaced in the pre-flight checklist.
 */
export const ICANN_TRANSFER_LOCK_DAYS = 60;

/** Typical real-world duration of an inbound transfer. Never imply it's instant. */
export const TRANSFER_TYPICAL_DAYS = "5–7 days";

/**
 * Give up on a transfer the registrar has stopped reporting on. Long enough to
 * cover the 5-7 day norm plus the registry's own auto-approval window.
 */
export const TRANSFER_STALE_DAYS = 14;

/** Integer cents the customer is charged for transferring `domain` in. */
export function transferChargeCents(priceCents: number): number {
  return domainTermPriceCents(priceCents, TRANSFER_TERM_YEARS);
}

/**
 * The exact charge description. Used verbatim at charge time AND to find the
 * invoice again when refunding, so the two always line up.
 */
export function transferChargeDescription(domain: string): string {
  return `Domain transfer in: ${domain} (includes 1 extra year)`;
}

/* ------------------------------------------------------------------ *
 * Duplicate-submit guard (same shape as lib/actions-domains.ts).
 *
 * Layer 1 (here, in-process): stops a double-click or an impatient retry from
 * reaching the registrar twice. Best-effort — does not survive a restart.
 * Layer 2 (authoritative): `Domain.name` is UNIQUE and the row write happens
 * inside the same `$transaction` as the wallet debit, so a duplicate can never
 * both take money and create a second row.
 * ------------------------------------------------------------------ */

const SUBMIT_GUARD_MS = 120_000;
const inFlight = new Map<string, number>();

export function beginTransferSubmit(key: string): boolean {
  const now = Date.now();
  const heldUntil = inFlight.get(key);
  if (heldUntil !== undefined && heldUntil > now) return false;
  if (inFlight.size > 2000) {
    for (const [k, v] of inFlight) if (v <= now) inFlight.delete(k);
  }
  inFlight.set(key, now + SUBMIT_GUARD_MS);
  return true;
}

export function endTransferSubmit(key: string): void {
  inFlight.delete(key);
}

/* ------------------------------------------------------------------ *
 * Settlement
 * ------------------------------------------------------------------ */

export type FailedTransferSettlement = {
  domainId: string;
  /** Raw registrar status to persist for display (null when we never got one). */
  transferStatus: string | null;
  /** Customer-facing reason, stored on `Domain.error`. */
  reason: string;
};

/**
 * Terminal-fail an inbound transfer and credit back exactly what was charged.
 *
 * Idempotent by construction: the status change is a compare-and-swap from
 * TRANSFER_PENDING, and the credit only happens when that swap wins. A retried
 * sweep, a racing customer-initiated cancel, and a worker restart therefore all
 * converge on exactly ONE credit. Returns true when this call was the one that
 * settled it.
 *
 * Only call this once the money is genuinely owed back — i.e. the registrar has
 * confirmed the transfer failed or was cancelled. Never on an unknown state.
 */
export async function settleFailedTransferIn(s: FailedTransferSettlement): Promise<boolean> {
  const domain = await db.domain.findUnique({ where: { id: s.domainId } });
  if (!domain || domain.status !== "TRANSFER_PENDING") return false;

  const refundCents = transferChargeCents(domain.priceCents);
  const description = transferChargeDescription(domain.name);

  return db.$transaction(async (tx) => {
    const swapped = await tx.domain.updateMany({
      where: { id: s.domainId, status: "TRANSFER_PENDING" },
      data: {
        status: "TRANSFER_FAILED",
        transferStatus: s.transferStatus,
        error: s.reason.slice(0, 500),
        // The customer's credential at their old registrar is no longer needed.
        transferAuthCodeEnc: null,
      },
    });
    if (swapped.count === 0) return false; // someone else already settled it

    if (refundCents > 0) {
      await tx.user.update({
        where: { id: domain.userId },
        data: { balanceCents: { increment: refundCents } },
      });
      await tx.walletTransaction.create({
        data: {
          userId: domain.userId,
          amountCents: refundCents,
          description: `Refund: transfer of ${domain.name} did not complete`,
        },
      });
      // Keep the ledger honest: the original PAID invoice becomes REFUNDED.
      // Matched on the exact description we stamped at charge time.
      await tx.invoice.updateMany({
        where: { userId: domain.userId, description, status: "PAID" },
        data: { status: "REFUNDED" },
      });
    }
    await tx.auditLog.create({
      data: {
        userId: domain.userId,
        action: "domain.transfer_in.refunded",
        detail: `${domain.name}: ${refundCents}c credited — ${s.reason}`.slice(0, 500),
      },
    });
    return true;
  });
}

/**
 * Mark an inbound transfer complete: the domain is ours to manage now. Scrubs
 * the stored auth code — we keep someone else's registrar credential no longer
 * than the transfer needs it. CAS-guarded, so it lands exactly once.
 */
export async function settleCompletedTransferIn(opts: {
  domainId: string;
  transferStatus: string;
  registeredAt: Date | null;
  expiresAt: Date;
}): Promise<boolean> {
  const res = await db.domain.updateMany({
    where: { id: opts.domainId, status: "TRANSFER_PENDING" },
    data: {
      status: "ACTIVE",
      transferStatus: opts.transferStatus,
      transferAuthCodeEnc: null,
      error: null,
      ...(opts.registeredAt ? { registeredAt: opts.registeredAt } : {}),
      expiresAt: opts.expiresAt,
    },
  });
  return res.count > 0;
}

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { encryptSecret } from "./crypto-box";
import { getSettingBool } from "./settings";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";
import {
  transfersAvailable,
  checkTransfer,
  createTransfer,
  cancelTransfer,
  type TransferCheck,
} from "./registrar";
import {
  TRANSFER_TERM_YEARS,
  beginTransferSubmit,
  endTransferSubmit,
  settleFailedTransferIn,
  transferChargeCents,
  transferChargeDescription,
} from "./domain-transfer";

const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;

/** Statuses a customer may retry a transfer over (nothing live is clobbered). */
const RETRYABLE = ["FAILED", "TRANSFER_FAILED"] as const;

function errMsg(e: unknown): string {
  return String(e instanceof Error ? e.message : e).slice(0, 200);
}

/** Never let a registrar error echo the customer's auth code back into the UI/logs. */
function scrubbed(msg: string, authCode: string): string {
  return authCode ? msg.split(authCode).join("***") : msg;
}

class DuplicateDomainError extends Error {
  constructor() {
    super("DUPLICATE_DOMAIN");
    this.name = "DuplicateDomainError";
  }
}

const isUniqueConflict = (e: any) => e?.code === "P2002";

/* ------------------------------------------------------------------ *
 * Step 1 — quote
 * ------------------------------------------------------------------ */

export type TransferQuote = {
  domain: string;
  transferable: boolean;
  reason: string | null;
  /** RETAIL total the customer pays — the transfer plus a 1-year extension. */
  priceCents: number | null;
};

/**
 * Is this domain transferable, and what does it cost? Read-only; safe to call
 * repeatedly from the wizard. Rate-limited because every call fans out to the
 * registrar.
 */
export async function quoteTransferIn(raw: string): Promise<{ error?: string; quote?: TransferQuote }> {
  const user = await requireUser();
  if (!(await getSettingBool("feature_domains", true))) {
    return { error: "Domain transfers are currently unavailable." };
  }
  if (!transfersAvailable()) {
    return { error: "Domain transfers aren't configured yet (registrar API keys missing)." };
  }
  const rl = checkRateLimit(`domain-transfer-quote:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many lookups — try again in ${rl.retryAfterSec}s.` };

  const domain = raw.toLowerCase().trim().replace(/^https?:\/\//, "").replace(/\/.*$/, "");
  if (!DOMAIN_RE.test(domain)) return { error: "Enter a domain like example.com (no www, no path)." };

  const existing = await db.domain.findUnique({ where: { name: domain } });
  if (existing) {
    if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
    if (existing.status === "TRANSFER_PENDING") {
      return { error: "A transfer for this domain is already in progress on your account." };
    }
    if (!RETRYABLE.includes(existing.status as (typeof RETRYABLE)[number])) {
      return { error: `${domain} is already on your account (status: ${existing.status.toLowerCase()}).` };
    }
  }

  let check: TransferCheck;
  try {
    check = await checkTransfer(domain);
  } catch (e) {
    return { error: errMsg(e) };
  }
  return {
    quote: {
      domain,
      transferable: check.transferable && check.priceCents !== null,
      reason: check.reason,
      priceCents: check.priceCents === null ? null : transferChargeCents(check.priceCents),
    },
  };
}

/* ------------------------------------------------------------------ *
 * Steps 2-4 — pre-flight, auth code, submit
 * ------------------------------------------------------------------ */

/**
 * Submit an inbound transfer.
 *
 * ORDER MATTERS — the registrar is called BEFORE any money moves:
 *   1. re-quote server-side (the price the client showed is never trusted),
 *   2. `createTransfer` at the registrar,
 *   3. debit + invoice + Domain row, all in ONE transaction.
 *
 * So a charge for a transfer that was never submitted is structurally
 * impossible. A double charge is impossible three ways over: the in-process
 * guard blocks the double-click, `Domain.name` is UNIQUE inside the charging
 * transaction (and the retry path CAS-swaps off the exact status we read), and
 * name.com itself refuses a second transfer for a domain already in flight.
 *
 * If the debit fails after a successful submit (balance drained in the seconds
 * between the check and the charge) we cancel the transfer back out at the
 * registrar rather than quietly performing work nobody paid for.
 */
export async function submitTransferIn(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  // Spend path: never move a customer's money while an admin is impersonating.
  await assertNotImpersonating();

  if (!(await getSettingBool("feature_domains", true))) {
    return { error: "Domain transfers are currently unavailable." };
  }
  if (!transfersAvailable()) {
    return { error: "Domain transfers aren't configured yet (registrar API keys missing)." };
  }
  const rl = checkRateLimit(`domain-transfer-in:${user.id}`, { max: 5, windowMs: 10 * 60_000 });
  if (!rl.ok) {
    return { error: `Too many transfer attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)} min.` };
  }

  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };

  const authCode = String(formData.get("authCode") ?? "").trim();
  if (authCode.length < 4 || authCode.length > 255) {
    return { error: "Enter the EPP / auth code from your current registrar (4–255 characters)." };
  }

  // The pre-flight checklist is a real gate, not decoration: the registry will
  // reject a transfer that fails any of these, and the customer eats a 5-7 day
  // round trip for nothing. Confirm every box came back ticked.
  const acks = ["ackUnlocked", "ackPrivacy", "ackAge", "ackApproval"];
  if (acks.some((k) => formData.get(k) !== "1")) {
    return { error: "Confirm every pre-flight item before we submit the transfer." };
  }

  const expectedCents = Math.round(Number(formData.get("expectedCents") ?? 0));

  const guardKey = `transfer-in:${user.id}:${domain}`;
  if (!beginTransferSubmit(guardKey)) {
    return { error: "That transfer is already being submitted — give it a moment before retrying." };
  }

  try {
    const existing = await db.domain.findUnique({ where: { name: domain } });
    if (existing) {
      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
      if (existing.status === "TRANSFER_PENDING") {
        return { error: "A transfer for this domain is already in progress — you have not been charged twice." };
      }
      if (!RETRYABLE.includes(existing.status as (typeof RETRYABLE)[number])) {
        return { error: `${domain} is already on your account (status: ${existing.status.toLowerCase()}).` };
      }
    }

    // Re-quote server-side. The wizard's number is a display; this is the price.
    let check: TransferCheck;
    try {
      check = await checkTransfer(domain);
    } catch (e) {
      return { error: errMsg(e) };
    }
    if (!check.transferable || check.priceCents === null || check.costCents === null) {
      return { error: check.reason ?? "This domain can't be transferred in right now." };
    }
    const totalCents = transferChargeCents(check.priceCents); // retail — what we charge
    const registrarCostCents = check.costCents; // cost — what we tell name.com to spend

    if (expectedCents !== totalCents) {
      return {
        error:
          `The registrar's price changed while you were filling this in — it's now $${(totalCents / 100).toFixed(2)}. ` +
          `Go back a step to re-check and confirm the new price. Nothing has been charged.`,
      };
    }
    if (user.balanceCents < totalCents) {
      return { error: `Insufficient balance — this transfer costs $${(totalCents / 100).toFixed(2)}.` };
    }

    // ---- Registrar first. No money has moved at this point. ----
    let submitted;
    try {
      submitted = await createTransfer(domain, authCode, registrarCostCents);
    } catch (e) {
      return { error: `The registrar refused the transfer: ${scrubbed(errMsg(e), authCode)} (you were not charged).` };
    }

    // Recorded BEFORE the charge so that even a hard crash here leaves ops a
    // trace of a transfer that is live at the registrar but not yet billed.
    await db.auditLog
      .create({
        data: {
          userId: user.id,
          action: "domain.transfer_in.submitted",
          detail: `${domain} status=${submitted.status} charge=${totalCents}c`,
        },
      })
      .catch(() => {});

    // ---- Charge + row, atomically. ----
    let domainId: string;
    try {
      domainId = await db.$transaction(async (tx) => {
        const transferData = {
          status: "TRANSFER_PENDING" as const,
          isTransferIn: true,
          transferAuthCodeEnc: encryptSecret(authCode),
          transferStartedAt: new Date(),
          transferStatus: submitted.status,
          transferEmail: submitted.email,
          priceCents: check.priceCents!,
          costCents: check.costCents!,
          termYears: TRANSFER_TERM_YEARS,
          registrar: "name.com",
          error: null,
        };
        // Write the row FIRST: a unique conflict or a lost CAS aborts the whole
        // transaction before the wallet is touched.
        let id: string;
        if (existing) {
          const swapped = await tx.domain.updateMany({
            where: { id: existing.id, status: existing.status },
            data: transferData,
          });
          if (swapped.count === 0) throw new DuplicateDomainError();
          id = existing.id;
        } else {
          const created = await tx.domain.create({
            data: { name: domain, userId: user.id, ...transferData },
          });
          id = created.id;
        }
        await debitWallet(tx, user.id, totalCents);
        await tx.walletTransaction.create({
          data: {
            userId: user.id,
            amountCents: -totalCents,
            description: transferChargeDescription(domain),
          },
        });
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: user.id,
            description: transferChargeDescription(domain),
            status: "PAID",
            lineItems: [
              {
                description: `Domain transfer in — ${domain} (adds 1 year to the registration)`,
                qty: 1,
                unitCents: totalCents,
                amountCents: totalCents,
              },
            ],
          }),
        });
        return id;
      });
    } catch (e) {
      // The transfer IS live at the registrar but we could not bill it. Undo the
      // submission rather than do unpaid work; if the registrar won't cancel,
      // flag it for ops instead of silently swallowing it.
      let cancelled = false;
      try {
        await cancelTransfer(domain);
        cancelled = true;
      } catch {
        /* registrar refused the cancel — ops has to unwind it manually */
      }
      await db.auditLog
        .create({
          data: {
            userId: user.id,
            action: "domain.transfer_in.uncharged",
            detail: `${domain}: submitted but not charged (${errMsg(e)}) — cancelled=${cancelled}`.slice(0, 500),
          },
        })
        .catch(() => {});

      if (e instanceof InsufficientBalanceError) {
        return {
          error: cancelled
            ? "Your balance dropped below the transfer price before we could charge it, so we cancelled the transfer at the registrar. Top up and try again — you were not charged."
            : "Your balance dropped below the transfer price before we could charge it. We've flagged this for our team — you were not charged. Please contact support before retrying.",
        };
      }
      if (e instanceof DuplicateDomainError || isUniqueConflict(e)) {
        return { error: "A transfer for this domain is already in progress — you have not been charged twice." };
      }
      throw e;
    }

    await db.notification
      .create({
        data: {
          userId: user.id,
          title: `Transfer started: ${domain}`,
          body:
            `We've submitted the transfer to the registrar. Inbound transfers normally take 5–7 days ` +
            `and you must approve a confirmation email from your CURRENT registrar before it can complete.`,
          href: `/dashboard/domains/${domainId}`,
        },
      })
      .catch(() => {});

    revalidatePath("/dashboard/domains");
    redirect(`/dashboard/domains/${domainId}`);
  } finally {
    endTransferSubmit(guardKey);
  }
}

/* ------------------------------------------------------------------ *
 * Cancel an in-flight transfer
 * ------------------------------------------------------------------ */

/**
 * Cancel an inbound transfer at the registrar and credit the customer back.
 *
 * The credit happens ONLY after the registrar confirms the cancellation — we do
 * not assume a refund we haven't been given. If the registrar refuses (the most
 * common reason being that the transfer already completed at the registry) we
 * say so and move no money.
 */
export async function cancelTransferIn(
  domainId: string
): Promise<{ error?: string; note?: string }> {
  const user = await requireUser();
  // Credits the wallet — same guard as every other money-moving action.
  await assertNotImpersonating();

  const domain = await db.domain.findUnique({ where: { id: domainId } });
  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
  if (!domain.isTransferIn || domain.status !== "TRANSFER_PENDING") {
    return { error: "There's no transfer in progress for this domain." };
  }

  const rl = checkRateLimit(`domain-transfer-cancel:${user.id}`, { max: 6, windowMs: 10 * 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const guardKey = `transfer-cancel:${domain.userId}:${domain.name}`;
  if (!beginTransferSubmit(guardKey)) return { error: "That cancellation is already being processed." };

  try {
    try {
      await cancelTransfer(domain.name);
    } catch (e) {
      return {
        error:
          `The registrar wouldn't cancel this transfer: ${errMsg(e)}. ` +
          `That usually means it has already gone through at the registry — refresh in a few minutes. ` +
          `Nothing has been credited or charged.`,
      };
    }

    const refundCents = domain.priceCents;
    const settled = await settleFailedTransferIn({
      domainId: domain.id,
      transferStatus: "cancelled",
      reason: "Transfer cancelled at your request.",
    });
    await db.auditLog
      .create({ data: { userId: user.id, action: "domain.transfer_in.cancelled", detail: domain.name } })
      .catch(() => {});
    revalidatePath(`/dashboard/domains/${domainId}`);
    revalidatePath("/dashboard/domains");

    return {
      note: settled
        ? `Transfer cancelled at the registrar and $${(refundCents / 100).toFixed(2)} credited back to your wallet.`
        : "This transfer had already been settled — no further credit was applied.",
    };
  } finally {
    endTransferSubmit(guardKey);
  }
}

