import { db } from "../lib/db";
import {
  registrarConfigured,
  renewDomain,
  transfersAvailable,
  getTransfer,
  domainInfo,
  transferOutcome,
  transferStatusLabel,
} from "../lib/registrar";
import {
  TRANSFER_STALE_DAYS,
  TRANSFER_TERM_YEARS,
  settleCompletedTransferIn,
  settleFailedTransferIn,
} from "../lib/domain-transfer";

  await domainAutoRenewSweep(now);

  // Poll in-flight inbound transfers on the same cadence as domain renewals —
  // domain upkeep all lives on one timer.
  try {
    await domainTransferInSweep(now);
  } catch (e) {
    console.error("[billing] domain transfer-in sweep error", e);
  }
}

/* ------------------------------------------------------------------ *
 * Inbound domain transfers (transfer-in)
 * ------------------------------------------------------------------ */

/** Remind the customer to approve the confirmation email at most this often. */
const TRANSFER_NUDGE_DAYS = 3;

/**
 * Poll every TRANSFER_PENDING domain and move it to its real state.
 *
 * An ICANN transfer takes ~5-7 days and only completes once the owner approves
 * an email from the LOSING registrar, so this is a slow poll, not a spinner:
 *   completed -> ACTIVE, dates taken from the registrar, auth code scrubbed
 *   failed    -> TRANSFER_FAILED, wallet credited back, reason recorded
 *   pending   -> raw registrar status refreshed for display, gentle nudge
 *
 * Every mutation goes through the shared CAS-guarded settle helpers, so a
 * re-run, two workers racing, or a customer cancelling at the same moment can
 * never credit the same transfer twice.
 */
async function domainTransferInSweep(now: Date) {
  if (!transfersAvailable()) return; // registrar not configured — skip silently

  const pending = await db.domain.findMany({
    where: { status: "TRANSFER_PENDING", isTransferIn: true },
  });

  for (const domain of pending) {
    try {
      const info = await getTransfer(domain.name, domain.transferStartedAt);

      // No transfer on record. Normal once a transfer settles and drops off the
      // registrar's list — resolve it against the account rather than guessing.
      if (!info) {
        const owned = await domainInfo(domain.name).catch(() => null);
        if (owned?.expires) {
          await completeTransferIn(domain, "completed", owned);
          continue;
        }
        const startedAt = domain.transferStartedAt ?? domain.createdAt;
        const ageDays = (now.getTime() - startedAt.getTime()) / DAY;
        if (ageDays > TRANSFER_STALE_DAYS) {
          await failTransferIn(
            domain,
            null,
            `The registrar has no record of this transfer after ${Math.round(ageDays)} days. It did not complete.`
          );
        }
        continue;
      }

      const outcome = transferOutcome(info.status);

      if (outcome === "completed") {
        const owned = await domainInfo(domain.name).catch(() => null);
        await completeTransferIn(domain, info.status, owned);
        continue;
      }

      if (outcome === "failed") {
        await failTransferIn(domain, info.status, transferStatusLabel(info.status));
        continue;
      }

      // Still in flight — keep the displayed registrar status fresh.
      if (info.status !== domain.transferStatus || (info.email && info.email !== domain.transferEmail)) {
        await db.domain.update({
          where: { id: domain.id },
          data: { transferStatus: info.status, ...(info.email ? { transferEmail: info.email } : {}) },
        });
      }
      await nudgeTransferApproval(domain, info.status, info.email, now);
    } catch (e) {
      // One unhappy domain must never abort the sweep. Nothing is settled and
      // no money moves on an unknown state — we simply try again next pass.
      console.error(`[billing] transfer-in poll failed for ${domain.name}`, e);
    }
  }
}

async function completeTransferIn(
  domain: { id: string; name: string; userId: string },
  rawStatus: string,
  owned: { expires?: Date; created?: Date } | null
) {
  const expiresAt = owned?.expires ?? new Date(Date.now() + TRANSFER_TERM_YEARS * 365 * DAY);
  const settled = await settleCompletedTransferIn({
    domainId: domain.id,
    transferStatus: rawStatus,
    registeredAt: owned?.created ?? new Date(),
    expiresAt,
  });
  if (!settled) return;

  await db.auditLog.create({
    data: { userId: domain.userId, action: "domain.transfer_in.completed", detail: domain.name },
  });
  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transferred in successfully`,
      body: `It's now managed here and expires ${expiresAt.toISOString().slice(0, 10)} — the transfer added a year. DNS and auto-renew are ready to set up.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
  console.log(`[billing] transfer-in completed for ${domain.name}`);
}

async function failTransferIn(
  domain: { id: string; name: string; userId: string; priceCents: number },
  rawStatus: string | null,
  reason: string
) {
  const settled = await settleFailedTransferIn({
    domainId: domain.id,
    transferStatus: rawStatus,
    reason,
  });
  if (!settled) return;

  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transfer did not complete`,
      body: `${reason} We've credited $${(domain.priceCents / 100).toFixed(2)} back to your wallet. The most common cause is the confirmation email from your old registrar not being approved in time — you can start a new transfer whenever you're ready.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
  console.log(`[billing] transfer-in failed for ${domain.name}: ${reason}`);
}

/**
 * Nothing completes until the customer approves the losing registrar's email,
 * and that email is easy to miss. Nudge once every few days while we're waiting
 * — deduped on the notification log, same as the other billing reminders.
 */
async function nudgeTransferApproval(
  domain: { id: string; name: string; userId: string; transferStartedAt: Date | null; createdAt: Date },
  rawStatus: string,
  email: string | null,
  now: Date
) {
  const startedAt = domain.transferStartedAt ?? domain.createdAt;
  if (now.getTime() - startedAt.getTime() < 2 * DAY) return; // give them room first

  const already = await db.notification.findFirst({
    where: {
      userId: domain.userId,
      title: { contains: domain.name },
      AND: { title: { contains: "still waiting" } },
      createdAt: { gt: new Date(now.getTime() - TRANSFER_NUDGE_DAYS * DAY) },
    },
  });
  if (already) return;

  await db.notification.create({
    data: {
      userId: domain.userId,
      title: `${domain.name} transfer is still waiting`,
      body:
        `Registrar status: ${transferStatusLabel(rawStatus)}. ` +
        (email ? `Check ${email} ` : "Check the inbox for the domain's registered contact ") +
        `for the confirmation email from your CURRENT registrar and approve it. Transfers normally take 5–7 days and expire if the approval never arrives.`,
      href: `/dashboard/domains/${domain.id}`,
    },
  });
}

