"use client";

import { useActionState, useState, useTransition } from "react";
import Link from "next/link";
import { submitTransferIn, quoteTransferIn, type TransferQuote } from "@/lib/actions-domains-transfer";
import { fmtMoney } from "@/components/ui/primitives";

const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;

const STEPS = ["Domain", "Pre-flight", "Auth code", "Review"] as const;

/**
 * The four things a registry actually checks. Every one of them is a hard gate:
 * fail any and the transfer is rejected days later, so we make the customer
 * confirm each explicitly rather than discovering it at the end.
 */
const PREFLIGHT = [
  {
    key: "unlocked" as const,
    title: "The domain is unlocked at your current registrar",
    body: "Registrars ship domains locked (“registrar lock” / “transfer lock”). Find the domain in your old registrar's control panel and switch the lock off — the transfer is rejected while it's on.",
  },
  {
    key: "privacy" as const,
    title: "WHOIS privacy is off, or you can still get the auth code",
    body: "Some registrars hide the auth code and block the confirmation email while privacy is enabled. If yours does, turn privacy off for the duration of the transfer. We re-enable privacy here once the domain lands.",
  },
  {
    key: "age" as const,
    title: "It's more than 60 days since registration or its last transfer",
    body: "This is an ICANN rule, not our policy, and no registrar can waive it. A domain registered or transferred in the last 60 days will be rejected. The same applies if you changed the registrant contact in the last 60 days.",
  },
  {
    key: "approval" as const,
    title: "You can receive and approve the confirmation email",
    body: "Your CURRENT registrar emails the domain's registered contact to confirm the transfer. Nothing completes until you click the approval link — if that inbox is dead or the address is stale, fix it before starting.",
  },
];

function Stepper({ step }: { step: number }) {
  return (
    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
      {STEPS.map((s, i) => (
        <div key={s} className="flex items-center gap-2">
          <span
            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold transition-colors ${
              i === step
                ? "border-brand-400 bg-brand-500/20 text-brand-200"
                : i < step
                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 text-slate-500"
            }`}
          >
            {i < step ? "✓" : i + 1}
          </span>
          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
          {i < STEPS.length - 1 && <span className="mx-1 text-slate-700">→</span>}
        </div>
      ))}
    </div>
  );
}

export function DomainTransferInWizard({
  initialDomain,
  balanceCents,
}: {
  initialDomain: string;
  balanceCents: number;
}) {
  const [state, action, pending] = useActionState(submitTransferIn, {} as { error?: string });

  const [step, setStep] = useState(0);
  const [domain, setDomain] = useState(initialDomain);
  const [quote, setQuote] = useState<TransferQuote | null>(null);
  const [quoteError, setQuoteError] = useState<string | null>(null);
  const [checking, startCheck] = useTransition();

  const [acks, setAcks] = useState({ unlocked: false, privacy: false, age: false, approval: false });
  const [authCode, setAuthCode] = useState("");
  const [showCode, setShowCode] = useState(false);

  function check() {
    const name = domain.toLowerCase().trim();
    setDomain(name);
    startCheck(async () => {
      setQuoteError(null);
      setQuote(null);
      const res = await quoteTransferIn(name);
      if (res.error) setQuoteError(res.error);
      else if (res.quote) {
        setQuote(res.quote);
        if (!res.quote.transferable) setQuoteError(res.quote.reason ?? "This domain can't be transferred in.");
      }
    });
  }

  const priceCents = quote?.priceCents ?? null;
  const domainOk = DOMAIN_RE.test(domain) && !!quote && quote.transferable && priceCents !== null;
  const allAcked = Object.values(acks).every(Boolean);
  const codeOk = authCode.trim().length >= 4 && authCode.trim().length <= 255;
  const afterCents = balanceCents - (priceCents ?? 0);

  const canContinue =
    (step === 0 && domainOk) || (step === 1 && allAcked) || (step === 2 && codeOk) || step === 3;
  const isLast = step === STEPS.length - 1;

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_320px]">
      <form action={action} className="card">
        {/* hidden fields submitted to submitTransferIn */}
        <input type="hidden" name="domain" value={domain} />
        <input type="hidden" name="authCode" value={authCode.trim()} />
        <input type="hidden" name="expectedCents" value={priceCents ?? 0} />
        <input type="hidden" name="ackUnlocked" value={acks.unlocked ? "1" : "0"} />
        <input type="hidden" name="ackPrivacy" value={acks.privacy ? "1" : "0"} />
        <input type="hidden" name="ackAge" value={acks.age ? "1" : "0"} />
        <input type="hidden" name="ackApproval" value={acks.approval ? "1" : "0"} />

        <Stepper step={step} />

        {state?.error && (
          <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
            {state.error}
          </div>
        )}

        {/* STEP 1 — DOMAIN */}
        {step === 0 && (
          <div>
            <h2 className="mb-1 font-semibold">Which domain are you bringing over?</h2>
            <p className="mb-4 text-sm text-slate-400">
              Enter a domain you already own somewhere else. We&apos;ll ask the registrar whether it can be
              transferred and what it costs.
            </p>

            <div className="flex flex-wrap items-center gap-2">
              <input
                className="input max-w-sm font-mono"
                placeholder="example.com"
                value={domain}
                autoComplete="off"
                spellCheck={false}
                onChange={(e) => {
                  setDomain(e.target.value);
                  setQuote(null);
                  setQuoteError(null);
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    if (DOMAIN_RE.test(domain.toLowerCase().trim())) check();
                  }
                }}
              />
              <button
                type="button"
                className="btn-secondary"
                disabled={checking || !DOMAIN_RE.test(domain.toLowerCase().trim())}
                onClick={check}
              >
                {checking ? "Checking…" : "Check transfer"}
              </button>
            </div>

            {quote?.transferable && priceCents !== null && (
              <div className="mt-5 rounded-xl border border-emerald-500/30 bg-emerald-500/[0.06] p-4">
                <div className="flex flex-wrap items-center justify-between gap-3">
                  <span className="font-mono text-base font-semibold">{quote.domain}</span>
                  <span className="text-sm font-semibold text-emerald-400">
                    transferable · {fmtMoney(priceCents)}
                  </span>
                </div>
                <p className="mt-2 text-sm text-slate-300">
                  That one-off fee <span className="font-semibold text-white">adds a full year</span> to the
                  domain&apos;s registration — you don&apos;t lose the time you&apos;ve already paid for at your
                  old registrar, the new year is stacked on top of your current expiry date.
                </p>
                <p className="mt-2 text-xs text-slate-500">
                  It then renews here at {fmtMoney(priceCents)}/yr. WHOIS privacy is included.
                </p>
              </div>
            )}

            {quoteError && (
              <div className="mt-5 rounded-xl border border-amber-500/30 bg-amber-500/[0.06] px-4 py-3 text-sm text-amber-200">
                {quoteError}
                {quoteError.includes("register it instead") && (
                  <>
                    {" "}
                    <Link
                      href={`/dashboard/domains/register?domain=${encodeURIComponent(domain)}`}
                      className="font-semibold underline"
                    >
                      Register {domain}
                    </Link>
                  </>
                )}
              </div>
            )}

            <div className="mt-6 rounded-xl border border-white/10 bg-white/[0.02] px-4 py-3">
              <p className="text-sm font-medium text-slate-200">How long this takes</p>
              <p className="mt-1 text-sm text-slate-400">
                Inbound transfers typically take <span className="font-semibold text-slate-200">5–7 days</span>.
                They are run by the domain registries, not by us, and they cannot be rushed. Your website and
                email keep working the whole time — nothing goes down when a domain changes registrar.
              </p>
            </div>
          </div>
        )}

        {/* STEP 2 — PRE-FLIGHT */}
        {step === 1 && (
          <div>
            <h2 className="mb-1 font-semibold">Before we submit</h2>
            <p className="mb-4 text-sm text-slate-400">
              All four have to be true or the registry will reject the transfer days from now. Tick each one
              once you&apos;ve actually checked it — we can&apos;t verify them from here.
            </p>

            <div className="space-y-3">
              {PREFLIGHT.map((item) => {
                const on = acks[item.key];
                return (
                  <button
                    type="button"
                    key={item.key}
                    onClick={() => setAcks((a) => ({ ...a, [item.key]: !a[item.key] }))}
                    className={`flex w-full gap-3 rounded-xl border p-4 text-left transition ${
                      on ? "border-emerald-500/40 bg-emerald-500/[0.06]" : "border-white/10 bg-white/[0.02] hover:border-white/20"
                    }`}
                  >
                    <span
                      className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-md border text-[11px] font-bold ${
                        on ? "border-emerald-400 bg-emerald-500/20 text-emerald-300" : "border-white/20 text-transparent"
                      }`}
                    >
                      ✓
                    </span>
                    <span>
                      <span className={`block text-sm font-medium ${on ? "text-white" : "text-slate-200"}`}>
                        {item.title}
                      </span>
                      <span className="mt-1 block text-xs leading-relaxed text-slate-400">{item.body}</span>
                    </span>
                  </button>
                );
              })}
            </div>

            {!allAcked && (
              <p className="mt-4 text-xs text-slate-500">
                Confirm all four to continue. If one of them isn&apos;t true yet, sort it out at your current
                registrar first — starting early just burns a week.
              </p>
            )}
          </div>
        )}

        {/* STEP 3 — AUTH CODE */}
        {step === 2 && (
          <div>
            <h2 className="mb-1 font-semibold">Your EPP / auth code</h2>
            <p className="mb-4 text-sm text-slate-400">
              Your current registrar issues this (it may be called an “auth code”, “EPP code”, “transfer key”
              or “authorization code”). It usually appears in the domain&apos;s settings, or they email it to
              the registered contact on request.
            </p>

            <label className="label">Auth code for {domain}</label>
            <div className="flex max-w-md items-center gap-2">
              <input
                className="input font-mono"
                type={showCode ? "text" : "password"}
                value={authCode}
                autoComplete="off"
                spellCheck={false}
                maxLength={255}
                placeholder="e.g. Xk4!92mQ-aZ"
                onChange={(e) => setAuthCode(e.target.value)}
              />
              <button
                type="button"
                className="btn-secondary px-2.5 py-2 text-xs"
                onClick={() => setShowCode((v) => !v)}
              >
                {showCode ? "Hide" : "Show"}
              </button>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Stored encrypted, used once to authorize this transfer, and deleted as soon as the transfer
              finishes. It is never written to our logs.
            </p>

            {authCode && !codeOk && (
              <p className="mt-3 text-sm text-amber-300">
                That looks too short — auth codes are at least 4 characters.
              </p>
            )}

            <div className="mt-6 rounded-xl border border-white/10 bg-white/[0.02] px-4 py-3 text-sm">
              <p className="font-medium text-slate-200">Wrong or expired codes fail slowly</p>
              <p className="mt-1 text-slate-400">
                The registry only validates the code after we submit, so a typo shows up as a rejection rather
                than an instant error. Copy and paste it if you can.
              </p>
            </div>
          </div>
        )}

        {/* STEP 4 — REVIEW */}
        {step === 3 && (
          <div>
            <h2 className="mb-4 font-semibold">Review &amp; start the transfer</h2>
            <dl className="space-y-2.5 text-sm">
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Domain</dt>
                <dd className="font-mono">{domain}</dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">What you get</dt>
                <dd className="text-right">Transfer + 1 year added</dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Auth code</dt>
                <dd className="font-mono text-slate-400">
                  {"•".repeat(Math.min(12, authCode.trim().length))}
                </dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">WHOIS privacy</dt>
                <dd className="text-emerald-400">Included free</dd>
              </div>
              <div className="divider" />
              <div className="flex items-center justify-between text-base font-semibold">
                <dt>Due today</dt>
                <dd>{priceCents !== null ? fmtMoney(priceCents) : "—"}</dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Wallet balance</dt>
                <dd>{fmtMoney(balanceCents)}</dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-slate-400">Balance after</dt>
                <dd className={afterCents < 0 ? "font-semibold text-red-400" : "text-emerald-400"}>
                  {fmtMoney(afterCents)}
                </dd>
              </div>
            </dl>

            {afterCents < 0 && (
              <div className="mt-4 rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
                Insufficient balance.{" "}
                <Link href="/dashboard/billing" className="font-semibold underline">
                  Add funds
                </Link>{" "}
                before starting the transfer.
              </div>
            )}

            <div className="mt-5 rounded-xl border border-white/10 bg-white/[0.02] px-4 py-3 text-sm">
              <p className="font-medium text-slate-200">What happens after you click</p>
              <ol className="mt-2 list-decimal space-y-1 pl-5 text-slate-400">
                <li>We submit the transfer to the registry and charge your wallet.</li>
                <li>
                  <span className="text-slate-200">Your current registrar emails you</span> — you must approve
                  that email. Nothing moves until you do.
                </li>
                <li>The registry completes the transfer, normally within 5–7 days of approval.</li>
                <li>The domain appears here as active with a year added to its expiry.</li>
              </ol>
              <p className="mt-3 text-xs text-slate-500">
                You can cancel while it&apos;s in progress. We credit your wallet back as soon as the registrar
                confirms the cancellation — we don&apos;t credit before that, because until they confirm it, the
                transfer may still complete.
              </p>
            </div>
          </div>
        )}

        {/* NAV */}
        <div className="mt-6 flex items-center justify-between">
          <button
            type="button"
            className="btn-ghost"
            disabled={step === 0}
            onClick={() => setStep((s) => Math.max(0, s - 1))}
          >
            ← Back
          </button>
          {!isLast ? (
            <button
              type="button"
              className="btn-primary"
              disabled={!canContinue}
              onClick={() => setStep((s) => s + 1)}
            >
              Continue →
            </button>
          ) : (
            <button
              className="btn-primary px-6"
              disabled={pending || !domainOk || !allAcked || !codeOk || afterCents < 0}
            >
              {pending ? "Submitting…" : `Start transfer — ${priceCents !== null ? fmtMoney(priceCents) : ""}`}
            </button>
          )}
        </div>
      </form>

      {/* SUMMARY ASIDE */}
      <aside className="space-y-4">
        <div className="card">
          <p className="section-label mb-3">Transfer summary</p>
          <dl className="space-y-2.5 text-sm">
            <div className="flex justify-between gap-2">
              <dt className="text-slate-400">Domain</dt>
              <dd className="truncate font-mono">{domain || "—"}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Includes</dt>
              <dd>+1 year</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-400">Typical time</dt>
              <dd>5–7 days</dd>
            </div>
            <div className="divider" />
            <div className="flex justify-between text-base font-semibold">
              <dt>Due today</dt>
              <dd>{priceCents !== null ? fmtMoney(priceCents) : "—"}</dd>
            </div>
          </dl>
        </div>
        <p className="text-xs text-slate-500">
          Charged from your wallet only once the registrar accepts the transfer — if they reject it, nothing
          leaves your balance. If it fails later, we credit the full amount back automatically.
        </p>
      </aside>
    </div>
  );
}

import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { transfersAvailable } from "@/lib/registrar";
import { PageHeader, EmptyState } from "@/components/ui/primitives";
import { DomainTransferInWizard } from "@/components/customer/DomainTransferInWizard";

export const dynamic = "force-dynamic";

const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;

export default async function TransferDomainInPage({
  searchParams,
}: {
  searchParams: Promise<{ domain?: string }>;
}) {
  const user = await requireUser();
  const { domain: raw } = await searchParams;
  const domain = (raw ?? "").toLowerCase().trim();

  if (!transfersAvailable()) {
    return (
      <div className="space-y-6">
        <PageHeader title="Transfer a domain in" />
        <EmptyState
          title="Domain transfers aren't available yet"
          sub="Transfers light up once the registrar integration is configured. Your existing domains stay manageable in the meantime."
          action={
            <Link href="/dashboard/domains" className="btn-primary">
              Back to domains
            </Link>
          }
        />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <PageHeader
        title="Transfer a domain in"
        sub="Bring a domain you own elsewhere over to Nxeon. Takes 5–7 days and adds a year."
      >
        <Link href="/dashboard/domains" className="btn-ghost">
          ← All domains
        </Link>
      </PageHeader>

      <DomainTransferInWizard
        initialDomain={DOMAIN_RE.test(domain) ? domain : ""}
        balanceCents={user.balanceCents}
      />
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { cancelTransferIn } from "@/lib/actions-domains-transfer";
import { Badge, fmtMoney } from "@/components/ui/primitives";

function daysSince(d: Date | null): number | null {
  if (!d) return null;
  return Math.floor((Date.now() - d.getTime()) / 86_400_000);
}

/**
 * Inbound-transfer status card for the domain detail page.
 *
 * Deliberately blunt about the two things customers get wrong: a transfer is
 * not instant (5-7 days), and it will silently expire unless they approve the
 * email their OLD registrar sends them.
 */
export function TransferInStatusCard({
  domainId,
  domainName,
  status,
  transferStatus,
  transferStatusLabel,
  transferEmail,
  transferStartedAt,
  priceCents,
  error,
}: {
  domainId: string;
  domainName: string;
  status: string;
  transferStatus: string | null;
  transferStatusLabel: string | null;
  transferEmail: string | null;
  transferStartedAt: string | null;
  priceCents: number;
  error: string | null;
}) {
  const router = useRouter();
  const [note, setNote] = useState<string | null>(null);
  const [cancelError, setCancelError] = useState<string | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [pending, start] = useTransition();

  const started = transferStartedAt ? new Date(transferStartedAt) : null;
  const age = daysSince(started);
  const pendingTransfer = status === "TRANSFER_PENDING";

  function doCancel() {
    start(async () => {
      setCancelError(null);
      setNote(null);
      const res = await cancelTransferIn(domainId);
      if (res?.error) setCancelError(res.error);
      else {
        setNote(res.note ?? "Transfer cancelled.");
        setConfirming(false);
        router.refresh();
      }
    });
  }

  if (status === "TRANSFER_FAILED") {
    return (
      <div className="card border-red-500/30 bg-red-500/[0.04]">
        <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
          <h2 className="font-semibold text-red-200">Transfer did not complete</h2>
          <Badge tone="red">{transferStatus ?? "failed"}</Badge>
        </div>
        <p className="text-sm text-slate-300">
          {error ?? "The registrar did not complete this transfer."}
        </p>
        <p className="mt-2 text-sm text-slate-400">
          We credited {fmtMoney(priceCents)} back to your wallet. The usual causes are the confirmation email
          from your old registrar never being approved, the domain still being locked, a wrong auth code, or
          the 60-day ICANN window. Fix whichever applies and start again — {domainName} is still yours at your
          current registrar, nothing was lost.
        </p>
        <div className="mt-4">
          <Link href={`/dashboard/domains/transfer?domain=${encodeURIComponent(domainName)}`} className="btn-secondary">
            Try the transfer again
          </Link>
        </div>
      </div>
    );
  }

  if (!pendingTransfer) return null;

  return (
    <div className="card border-amber-500/30 bg-amber-500/[0.05]">
      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
        <h2 className="font-semibold text-amber-100">Transfer in progress</h2>
        <Badge tone="amber">{transferStatus ?? "pending"}</Badge>
      </div>

      <p className="text-sm text-slate-200">
        {transferStatusLabel ?? "Waiting on the registrar."}
      </p>

      <div className="mt-4 rounded-xl border border-white/10 bg-navy-950/50 p-4">
        <p className="text-sm font-semibold text-white">What you need to do</p>
        <p className="mt-1 text-sm text-slate-300">
          Your <span className="font-semibold text-white">current</span> registrar sends a confirmation email
          to the domain&apos;s registered contact
          {transferEmail ? (
            <>
              {" "}
              — we&apos;re told that&apos;s <span className="font-mono text-slate-200">{transferEmail}</span>
            </>
          ) : null}
          . You have to open it and approve the transfer. Until you do, nothing happens, and the request
          eventually expires on its own.
        </p>
        <p className="mt-2 text-xs text-slate-400">
          Check spam too — these emails come from the losing registrar, not from us.
        </p>
      </div>

      <dl className="mt-4 space-y-2 text-sm">
        <div className="flex justify-between">
          <dt className="text-slate-400">Started</dt>
          <dd>
            {started ? started.toISOString().slice(0, 10) : "—"}
            {age !== null && (
              <span className="ml-2 text-xs text-slate-500">
                {age === 0 ? "today" : `${age} day${age === 1 ? "" : "s"} ago`}
              </span>
            )}
          </dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-slate-400">Typical duration</dt>
          <dd>5–7 days</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-slate-400">Paid</dt>
          <dd>{fmtMoney(priceCents)} · adds 1 year on completion</dd>
        </div>
      </dl>

      <p className="mt-4 text-xs text-slate-500">
        We re-check this with the registrar automatically — you don&apos;t need to keep this page open. Your
        site and email keep working at your current registrar throughout.
      </p>

      <div className="mt-5 border-t border-white/[0.06] pt-4">
        {!confirming ? (
          <button type="button" className="btn-secondary" disabled={pending} onClick={() => setConfirming(true)}>
            Cancel this transfer
          </button>
        ) : (
          <div className="rounded-xl border border-white/10 bg-navy-950/60 p-4">
            <p className="text-sm text-slate-200">Cancel the transfer of {domainName}?</p>
            <p className="mt-1 text-xs text-slate-400">
              We ask the registrar to withdraw it. Your wallet is credited {fmtMoney(priceCents)} back{" "}
              <span className="text-slate-300">only once the registrar confirms the cancellation</span> — we
              won&apos;t credit you on a maybe, because a transfer that has already reached the registry can
              still complete. If they refuse, nothing changes and we&apos;ll tell you why.
            </p>
            <div className="mt-3 flex flex-wrap gap-2">
              <button type="button" className="btn-primary" disabled={pending} onClick={doCancel}>
                {pending ? "Contacting registrar…" : "Yes, cancel it"}
              </button>
              <button
                type="button"
                className="btn-ghost"
                disabled={pending}
                onClick={() => setConfirming(false)}
              >
                Keep it going
              </button>
            </div>
          </div>
        )}
        {note && <p className="mt-3 text-sm text-emerald-300">{note}</p>}
        {cancelError && <p className="mt-3 text-sm text-red-400">{cancelError}</p>}
      </div>
    </div>
  );
}

